// spec: specs/addbusiness-step5-invoice-name.md (2.1–2.2) · кейс: .qa/tests/addbusiness-step5-invoice-name/ADDBIZ-INV-03.md
// seed: tests/seed.user.spec.ts · ПРОД: черновик «QA-TEST …» удаляется в afterEach; запуск только с QA_REAL_WRITE=1.
import { test, expect, Page } from '@playwright/test';
import {
  PKG2, PayCtl, REAL_WRITE, SKIP_REASON, choosePackageAndGoToStep5, deleteDraft, goToPackageStep,
  interceptWithPayments, invoiceField,
} from './invoice-name.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

async function inputValues(page: Page, ctl: PayCtl) {
  await goToPackageStep(page, ctl);
  await choosePackageAndGoToStep5(page, PKG2);
  const field = invoiceField(page);

  const hebrew = 'QA-AUTO חברת בדיקה בע"מ';
  await field.fill(hebrew);
  await expect(field, 'иврит с בע"מ принят без изменений').toHaveValue(hebrew);

  const latin = 'QA-AUTO Test Company Ltd';
  await field.fill(latin);
  await expect(field, 'латиница принята').toHaveValue(latin);

  // ввод с клавиатуры 120 символов → остаются первые 100 (maxlength=100)
  const long = 'QA-AUTO-' + 'א'.repeat(112);
  expect(long).toHaveLength(120);
  await field.fill('');
  await field.pressSequentially(long);
  await expect(field, 'обрезано до 100 символов').toHaveValue(long.slice(0, 100));

  // поле в пределах окна, без горизонтальной прокрутки страницы
  const box = await field.boundingBox();
  const width = page.viewportSize()!.width;
  expect(box, 'поле на экране').not.toBeNull();
  expect(box!.x, 'левый край в окне').toBeGreaterThanOrEqual(0);
  expect(box!.x + box!.width, 'правый край в окне').toBeLessThanOrEqual(width);
  expect(
    await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1),
    'нет горизонтальной прокрутки',
  ).toBe(true);
}

test.describe('Публикация бизнеса — шаг 5: ввод в «שם לחשבונית»', () => {
  let ctl: PayCtl | null = null;

  test.beforeEach(() => test.skip(!REAL_WRITE, SKIP_REASON));
  test.afterEach(async ({ page }) => {
    if (ctl) {
      expect(ctl.payments, 'платёж не запрашивался').toEqual([]);
      await deleteDraft(page, ctl);
    }
    ctl = null;
  });

  test('Иврит с בע"מ и латиница принимаются, больше 100 символов обрезается #8bea2a @desktop @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await inputValues(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: иврит, латиница, обрезка до 100, поле в пределах экрана #8bea2a @android @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await inputValues(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });
});
